slug: memoization-cache-key-missing-parameter
stack: dotnet
topic: performance
level: middle
type: find-bug
grading: auto
tags: [memoization, caching, dictionary, cache-key]
code:
  language: csharp
  harness: statements
  source: |
    Dictionary<string, decimal> cache = new();

    decimal LoadPrice(int productId, string currency)
    {
        // Stand-in for a slow call to a pricing service.
        return currency == "EUR" ? 92m : 100m;
    }

    decimal GetPrice(int productId, string currency)
    {
        string key = productId.ToString();
        if (cache.TryGetValue(key, out decimal cached))
        {
            return cached;
        }
        decimal price = LoadPrice(productId, currency);
        cache[key] = price;
        return price;
    }

    decimal usd = GetPrice(42, "USD");
    decimal eur = GetPrice(42, "EUR");
    Console.WriteLine($"USD {usd}, EUR {eur}");
bugLineSets: [[11]]
fixedSource: |
  Dictionary<string, decimal> cache = new();

  decimal LoadPrice(int productId, string currency)
  {
      // Stand-in for a slow call to a pricing service.
      return currency == "EUR" ? 92m : 100m;
  }

  decimal GetPrice(int productId, string currency)
  {
      string key = $"{productId}:{currency}";
      if (cache.TryGetValue(key, out decimal cached))
      {
          return cached;
      }
      decimal price = LoadPrice(productId, currency);
      cache[key] = price;
      return price;
  }

  decimal usd = GetPrice(42, "USD");
  decimal eur = GetPrice(42, "EUR");
  Console.WriteLine($"USD {usd}, EUR {eur}");
fixedExpect: { kind: output, value: "USD 100, EUR 92" }
